import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as n,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Gemini Canvas","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/gemini/canvas.md","filePath":"products/ai-coding/gemini/canvas.md","lastUpdated":1787042982000}'),o={name:"products/ai-coding/gemini/canvas.md"};function s(r,e,l,h,p,c){return n(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="gemini-canvas" tabindex="-1">Gemini Canvas <a class="header-anchor" href="#gemini-canvas" aria-label="Permalink to &quot;Gemini Canvas&quot;">​</a></h1><blockquote><p>A dynamic workspace inside the Gemini app. Its value is <strong>skipping project setup and getting straight to something clickable</strong>.</p></blockquote><h2 id="what-it-is-for" tabindex="-1">What it is for <a class="header-anchor" href="#what-it-is-for" aria-label="Permalink to &quot;What it is for&quot;">​</a></h2><p>In an ordinary conversation the AI can only hand you a block of code; you still have to create a project, install dependencies and run it before you see anything. Canvas removes that stretch — it gives you a workspace next to the conversation, and what it produces is directly interactive.</p><p><strong>It is positioned as a prototyping tool, not a source of production code.</strong> Once that is clear, every trade-off below follows naturally.</p><h2 id="core-features" tabindex="-1">Core features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core features&quot;">​</a></h2><p>The official page describes Canvas as an interactive space for creating and refining documents, code and web designs together with Gemini, with a live preview of the result.</p><p>The two points that matter most to developers:</p><p><strong>Visible iteration</strong>: the output is not a static code block. You can operate it, then base the next round of requests on &quot;the behaviour I saw&quot; rather than &quot;the behaviour I imagined while reading code&quot;.</p><p><strong>Local refinement</strong>: you can ask for changes to one part instead of regenerating the whole file each time. That saves a lot of time when tuning UI details.</p><h2 id="work-in-layers" tabindex="-1">Work in layers <a class="header-anchor" href="#work-in-layers" aria-label="Permalink to &quot;Work in layers&quot;">​</a></h2><p>This is the one methodology that matters when using Canvas.</p><p><strong>Anti-pattern</strong>: asking for a full-size application with complete business logic in one shot.</p><p>The problem is not that it cannot do it; it is that <strong>you lose the information about which step went wrong</strong>. Generate two hundred lines at once and your only recourse when something breaks is to start over.</p><p><strong>Instead</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Layer 1: DOM structure + basic interaction           → confirm the logic is on track</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Layer 2: apply the design system (Tailwind / CSS variables)  → keep the code tidy</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Layer 3: move into a real project for types and tests  → this step leaves Canvas</span></span></code></pre></div><p>Confirm at the end of each layer. <strong>Layer 3 means leaving Canvas</strong> — do not try to do the engineering inside it; that is not its strength.</p><h3 id="example-prompt" tabindex="-1">Example prompt <a class="header-anchor" href="#example-prompt" aria-label="Permalink to &quot;Example prompt&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Build a business dashboard from the JSON structure below, with a live revenue line chart and a churn rate pie chart:</span></span>
<span class="line"><span>- support a dark mode toggle</span></span>
<span class="line"><span>- responsive layout</span></span>
<span class="line"><span>- structure and interaction only for now, styling comes later</span></span></code></pre></div><p>The last line is the important one: it confines this round to layer 1.</p><h2 id="where-it-fits" tabindex="-1">Where it fits <a class="header-anchor" href="#where-it-fits" aria-label="Permalink to &quot;Where it fits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th style="text-align:center;">Fit</th><th>Notes</th></tr></thead><tbody><tr><td>One-off prototype</td><td style="text-align:center;">High</td><td>fastest path to validating an idea, no engineering investment</td></tr><tr><td>A small tool for non-technical colleagues</td><td style="text-align:center;">High</td><td>they can read something clickable, not code</td></tr><tr><td>Standalone lightweight micro-app</td><td style="text-align:center;">Medium</td><td>possible, but moving it out still needs engineering</td></tr><tr><td>Production application</td><td style="text-align:center;">Low</td><td>do not start a system with real reliability requirements here</td></tr></tbody></table><h2 id="choosing-between-this-and-the-others" tabindex="-1">Choosing between this and the others <a class="header-anchor" href="#choosing-between-this-and-the-others" aria-label="Permalink to &quot;Choosing between this and the others&quot;">​</a></h2><p>Canvas is off the engineering mainline, so it does not compete with the rest:</p><ul><li>want code you can <strong>commit to a repository</strong> → <a href="./gemini-cli.html">Gemini CLI</a> or <a href="./antigravity.html">Antigravity</a></li><li>want to <strong>see the result before deciding whether to build it</strong> → Canvas</li><li>want a <strong>landing-page / launch / product-demo video</strong> → <a href="./flow.html">Google Flow</a></li></ul><p>A genuinely useful combination: try three directions in Canvas, pick one, then have Antigravity implement it in the real project. When you present the feature, make the clip in Flow.</p><h2 id="official-resources" tabindex="-1">Official resources <a class="header-anchor" href="#official-resources" aria-label="Permalink to &quot;Official resources&quot;">​</a></h2><ul><li><a href="https://gemini.google/overview/canvas/" target="_blank" rel="noreferrer">Canvas overview</a></li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./gemini-cookbook.html#_13-a-clickable-prototype-fast">Cookbook</a> — the prototyping recipe</li><li><a href="./gemini-cheatsheet.html#pick-by-task">Cheatsheet</a> — pick a tool by task</li></ul>`,30)])])}const b=t(o,[["render",s]]);export{f as __pageData,b as default};
